import base64
from io import BytesIO
from PIL import Image


def _b64_to_image(b64_string: str) -> Image.Image:
    """将 Base64 字符串解码为 PIL Image 对象。"""
    return Image.open(BytesIO(base64.b64decode(b64_string)))


